import{_ as e}from"./chunks/3dots_menu.BrLPqWzo.js";import{_ as t,a as o,b as r,c as i,d as s,e as l}from"./chunks/3DM-BR-CB7.Bp-b42-4.js";import{_ as n}from"./chunks/BDM.scaBLLhv.js";import{_ as p}from"./chunks/DIS.DdpTdGGD.js";import{_ as c,o as d,c as u,a3 as h}from"./chunks/framework.g9mfNVRQ.js";const S=JSON.parse('{"title":"Reinstallation","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshoot/reinstall.md","filePath":"troubleshoot/reinstall.md"}'),m={name:"troubleshoot/reinstall.md"};function b(f,a,y,g,k,v){return d(),u("div",null,[...a[0]||(a[0]=[h('<h2 id="uninstall-xdrip" tabindex="-1">Uninstall xDrip <a class="header-anchor" href="#uninstall-xdrip" aria-label="Permalink to &quot;Uninstall xDrip&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Historical data</p><p>Uninstalling xDrip will also remove all data and settings without possible recovery.<br> Make sure you <strong><a href="#backup">back up</a></strong> database and/or all settings before.<br> It is recommended to upload data to <a href="https://nightscout.github.io/" target="_blank" rel="noreferrer">Nightscout</a>.</p></div><br><p>This shouldn&#39;t usually be necessary, but you might need to uninstall xDrip to troubleshoot, or if you need to change it to or from a forked version. You can uninstall xDrip like any other Android app with a long press on the icon or from Android Settings -&gt; Apps.</p><h2 id="reinstall-xdrip" tabindex="-1">Reinstall xDrip <a class="header-anchor" href="#reinstall-xdrip" aria-label="Permalink to &quot;Reinstall xDrip&quot;">​</a></h2><p>Follow this sequence:</p><ol><li>Backup (locally or in the cloud)</li><li>Uninstall xDrip</li><li>Install xDrip</li><li>Restore (from local or cloud backup)</li><li>Check all your settings and recreate your alarms</li></ol><h2 id="backup" tabindex="-1">Backup <a class="header-anchor" href="#backup" aria-label="Permalink to &quot;Backup&quot;">​</a></h2><p>You can either back up the database locally or in your <a href="#cloud-backup">Google Drive</a>.</p><h3 id="backup-the-database" tabindex="-1">Backup the database <a class="header-anchor" href="#backup-the-database" aria-label="Permalink to &quot;Backup the database&quot;">​</a></h3><p>The database contains all BG readings, treatments and notes. It is strongly recommended that you back up your database and keep a copy on another device if you want to keep your existing data and as a safety precaution against a phone loss, crash, ...<br> Using upload to <a href="https://nightscout.github.io/" target="_blank" rel="noreferrer">Nightscout</a> is also strongly recommended.</p><p>Exporting the database will also <a href="./../use/loadsavesettings.html#save-settings">save settings</a>.</p><p>From the main xDrip display select the upper right 3 dots menu, Import / Export features, Export database.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Import / Export features ►<br>  Export database</p></div><br><p>The current database will be saved in <code>/storage/emulated/0/xdrip</code> or <code>Internal Storage/xdrip</code> You need to authorize xDrip to access your phone memory.<br> You can make as many backups as your memory can store.</p><p>If you&#39;re fast enough to touch the <code>SHARE</code> writing before it disappears you can use your phone share options to send the database to another device or copy it to another location.</p><img src="'+t+'" style="zoom:75%;"><p>Your backup will be named <code>exportYYYYMMDD-HHMMSS.zip</code> with <code>YYYY</code> current year, <code>MM</code> month, <code>DD</code> day, and <code>HHMMSS</code> for hours, minutes and seconds. This will allow you to have multiple backups identified by a unique timestamp.</p><p>If you want to keep a safe copy, send the file to yourself by email, save it on a cloud drive or copy it via USB to a computer.</p><p>It is an SQLite database you can browse with various utilities like <a href="https://sqlitebrowser.org/" target="_blank" rel="noreferrer">SQLite Browser</a>.</p><br><h2 id="restore" tabindex="-1">Restore <a class="header-anchor" href="#restore" aria-label="Permalink to &quot;Restore&quot;">​</a></h2><p>You can restore the database from a local copy or from your <a href="#cloud-backup">Google Drive</a>.</p><h3 id="restore-settings" tabindex="-1">Restore settings <a class="header-anchor" href="#restore-settings" aria-label="Permalink to &quot;Restore settings&quot;">​</a></h3><p>When xDrip install is complete, if a backup is available, xDrip will propose to restore it automatically.<br> Select RESTORE SETTINGS</p><div class="admonition xdripitem"><p class="admonition-title">Backup detected</p><p> It looks like you maybe have a settings backup, shall we try to restore it?</p><p> NO    <span style="background-color:white;color:black;"> RESTORE SETTINGS </span></p></div><p>If you don&#39;t see this message, <a href="./../use/loadsavesettings.html#load-settings">restore them manually</a>.</p><h3 id="restore-a-database" tabindex="-1">Restore a database <a class="header-anchor" href="#restore-a-database" aria-label="Permalink to &quot;Restore a database&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Data loss</p><p>Restoring a database will <strong>delete all current data</strong>.<br> Restore a database with <strong>the same version of xDrip used to export it</strong>.<br> Make sure to back up the current database before restoring a database.</p></div><p>When xDrip install is complete, if a database backup is available, xDrip might propose to restore it automatically.</p><p>Make sure this is the database you want to restore, then select RESTORE.</p><div class="admonition xdripitem"><p class="admonition-title">Restore backup?</p><p> Do you want to restore the backup file: export20210328-085436.zip</p><p> NO    <span style="background-color:white;color:black;"> RESTORE </span></p></div><p>xDrip will confirm correct database restore.</p><div class="admonition xdripitem"><p class="admonition-title">Import Result</p><p> Successfully imported database</p></div><p><em>Note: the current database will be exported first, for safety; you will find it in the list named <code>b4import</code> and the date/time the import was done. This will allow you to recover it if necessary.</em></p><br><p>If you want to restore a specific backup, from the main xDrip display select the upper right 3 dots menu, Import / Export features, Restore database.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Import / Export features ►<br>  Restore database</p></div><p>Instructions are displayed. You don&#39;t need to move the backup file if you didn&#39;t move it from another device, and you don&#39;t need to unzip it. Be cautious when restoring a database with a different xDrip version: it is recommended that you install the <a href="./../install/install.html#verify-which-version-is-installed">xDrip version</a> that was used to perform the export before importing, then you can update xDrip.</p><div class="admonition xdripitem"><p class="admonition-title">Restore Instructions</p><p> WARNING: Database restore is rarely necessary and may cause SEVERE DATA LOSS.</p><p>Protect your data by uploading to Nightscout or Tidepool.</p><p>When switching phones, importing settings (alerts, colors, etc.) is usually sufficient. Restoring the database is typically unnecessary unless you need short-term access to historical data (for example, before a medical visit).</p><p>Instructions:</p><p>- Place the database in the &#39;xdrip&#39; folder. If it doesn&#39;t exist, perform an export once to create it.</p><p>- Restart this restore routine.</p><p>- Select the correct database and follow the on-screen instructions.</p></div><p>Select the database you want to import, look at the date and size (use the phone file browser) to be sure to pick the right one.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+n+'" style="zoom:75%;">Restore database</p><p>export20220129-184625.zip<br> export20220129-184615.zip<br> b4import20220129-194141.zip</p></div><p>Once sure you&#39;re trying to restore the correct backup, <code>Ok</code></p><div class="admonition xdripitem"><p class="admonition-title">Confirm Import</p><p> Do you really want to import<br>  &#39;export20220129-184615.zip&#39;?<br>  This may negatively affect the data integrity of your system!</p><p> CANCEL    <span style="background-color:white;color:black;"> OK </span></p></div><p>xDrip will confirm correct database restore.</p><div class="admonition xdripitem"><p class="admonition-title">Import Result</p><p> Successfully imported database</p></div><p>If you restored the wrong database, just redo the same steps and select the latest <code>b4import</code> version to roll back.</p><div class="info custom-block"><p class="custom-block-title">Android 11 and above</p><p>There is an issue with recent Android versions that will force you to restore the database several (3 to 4) times before you can see the full contents.</p></div><br><h2 id="cloud-backup" tabindex="-1">Cloud backup <a class="header-anchor" href="#cloud-backup" aria-label="Permalink to &quot;Cloud backup&quot;">​</a></h2><p>Cloud backup allows you to save a zipped file containing both database and settings in your Google Drive.<br> You must be logged in to your Google account to use this feature.</p><p>Select Cloud Backup.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Import / Export features ►<br>  Cloud backup</p></div><div class="admonition xdripitem"><p class="admonition-title">Cloud Backup</p><p>  You can use Google Drive for backup<br>        Ready</p></div><p>In order to use this feature you should first select a backup location.</p><h3 id="select-backup-location" tabindex="-1">Select backup location <a class="header-anchor" href="#select-backup-location" aria-label="Permalink to &quot;Select backup location&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title"><span style="background-color:white;color:black;"> Select Backup Location </span></p></div><div class="admonition xdripitem"><p class="admonition-title">Choose Backup File</p><p>  Select Automatic for xDrip to manage files in Google Drive or select an alternate specific file to use if you need to restore from elsewhere.</p><p>       <span style="background-color:white;color:black;"> AUTOMATICALLY MANAGE </span></p><p>        <span style="background-color:white;color:black;"> USE ALTERNATE FILE </span></p></div><ul><li>Use alternate file will allow you to select a different folder and backup file when <strong>restoring</strong>.</li><li>When doing your <strong>first backup</strong>, or when recovering <strong>an xDrip reinstall</strong> on the same phone, select Automatically manage.</li></ul><p>You must authorize xDrip to access your Google Account. xDrip will only store and retrieve the backup file from your Google Drive. <strong>Nothing else.</strong></p><img src="'+o+'" style="zoom:75%;"><p>Once done, xDrip will confirm access:</p><img src="'+r+'" style="zoom:75%;"><p>xDrip will create a new folder named xDrip-Backups in the root of your Google drive.</p><img src="'+i+'" style="zoom:75%;"><h3 id="do-backup-now" tabindex="-1">Do backup now <a class="header-anchor" href="#do-backup-now" aria-label="Permalink to &quot;Do backup now&quot;">​</a></h3><p>Once your backup location is selected, you can perform a backup. The backup file will be created on your device and then uploaded to your Google cloud drive.</p><div class="admonition xdrip"><p class="admonition-title"><span style="background-color:white;color:black;"> Do Backup Now </span></p></div><img src="'+s+'" style="zoom:75%;"><p>You can check cloud backup status at the top of the current view.</p><img src="'+l+'" style="zoom:75%;"><p>You can make cloud backup execute automatically every day.<br> Do not enable this if you&#39;re using a limited mobile data plan.</p><div class="admonition xdripitem"><p class="admonition-title"><img src="'+p+'" style="zoom:75%;"> Automatic daily backup</p></div><h3 id="restore-from-backup" tabindex="-1">Restore from backup <a class="header-anchor" href="#restore-from-backup" aria-label="Permalink to &quot;Restore from backup&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title"><span style="background-color:white;color:black;"> Restore From Backup </span></p></div><div class="warning custom-block"><p class="custom-block-title">Data loss</p><p>Restoring a database will delete all current data.<br> Restore a database with <strong>the same version of xDrip used to export it</strong>.<br> Make sure to back up the current database before restoring a database.</p></div><div class="admonition xdripitem"><p class="admonition-title">Are you really sure?</p><p> Restoring a backup will erase your current settings and data with that from the backup.</p><p> Are you absolutely sure you wish to do this?</p><p> NO    <span style="background-color:white;color:black;"> YES </span></p></div><p>Restore will copy the cloud database locally and replace the current database.</p><p>Once done, xDrip will restart.</p><br><h2 id="new-phone-migration" tabindex="-1">New phone migration <a class="header-anchor" href="#new-phone-migration" aria-label="Permalink to &quot;New phone migration&quot;">​</a></h2><p>Perform the following operations:</p><p>On the old phone:</p><ol><li><p><a href="#backup-the-database">Backup the database locally</a> or in your <a href="#do-backup-now">Google drive</a>.</p><ul><li>If you won&#39;t use Google cloud backup, send yourself the database backup, or copy it to a computer.</li></ul></li><li><p>If this old phone is connected to a sensor or a bridge, make sure to <a href="./../install/datasource.html#changing-data-source">disable collection</a> so that it won&#39;t interfere when you start using your new phone.</p></li><li><p>If this old phone was master for xDrip sync followers, <a href="./../use/sync.html#be-master-for-followers">remove the master role</a>.</p></li></ol><p>On the new phone:</p><ol><li><p><a href="./../install/download.html#which-one-to-install">Install</a> the <a href="./../install/install.html#verify-which-version-is-installed">same version</a> of xDrip you are using on the old phone.</p><ul><li>If you didn&#39;t use Google cloud backup:<br><a href="#backup-the-database">Backup the database</a> (this is only needed to create the correct folders).<br> Copy the database file you sent yourself via mail, or from a computer to the right folder.</li></ul></li><li><p><a href="#restore-a-database">Restore the database from the local backup</a> or from your <a href="#restore-from-backup">Google Drive</a>.</p></li><li><p>If the new phone is connected to a sensor or a bridge, <a href="./../install/datasource.html#sensor-selection">connect it now</a>. (Your data source will be correct but you&#39;ll need to recover connection).</p></li></ol><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Last modified 23/11/2026</em></a></p>',89)])])}const I=c(m,[["render",b]]);export{S as __pageData,I as default};
